import { useQuery } from '@tanstack/react-query';
import api from '../../api/axios';
import { Table, Badge } from '../../components/ui';

const statusColor = { PENDING: 'yellow', COMPLETED: 'green', IN_PROGRESS: 'blue' };

export default function OnboardingPage() {
  const { data, isLoading } = useQuery({
    queryKey: ['onboarding'],
    queryFn: () => api.get('/onboarding', { params: { page: 0, size: 20 } }),
  });

  const items = data?.data?.data?.content || data?.data?.data || [];

  const columns = [
    { key: 'employeeName', label: 'Employee' },
    { key: 'taskName', label: 'Task' },
    { key: 'assignedTo', label: 'Assigned To' },
    { key: 'dueDate', label: 'Due Date' },
    { key: 'status', label: 'Status', render: (r) => <Badge label={r.status} color={statusColor[r.status] || 'gray'} /> },
  ];

  return (
    <div className="space-y-4">
      <div className="bg-indigo-50 border border-indigo-200 rounded-xl p-4 text-sm text-indigo-700">
        Onboarding checklists are auto-created when a new employee joins. Track task completion here.
      </div>
      <Table columns={columns} data={items} loading={isLoading} />
    </div>
  );
}
